import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';

interface ConversationSummary {
  id: string;
  title: string;
  updatedAt: string;
  messageCount: number;
}

async function fetchConversations(tenantId: string, token: string): Promise<ConversationSummary[]> {
  const res = await fetch(`/api/conversations?tenantId=${tenantId}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error(`Failed to fetch conversations: ${res.status}`);
  return res.json();
}

export function useConversations(tenantId: string, token: string) {
  return useQuery({
    // Scoped cache key: changes to tenantId invalidate this query independently
    queryKey: ['conversations', tenantId],
    queryFn: () => fetchConversations(tenantId, token),
    staleTime: 1000 * 60 * 2, // Data considered fresh for 2 minutes
    refetchOnWindowFocus: true, // Refresh when user returns to tab
    enabled: Boolean(tenantId && token), // Only fetch when auth is ready
  });
}

export function useRenameConversation(tenantId: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, title }: { id: string; title: string }) =>
      fetch(`/api/conversations/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title }),
      }).then((r) => { if (!r.ok) throw new Error(r.statusText); }),

    onMutate: async ({ id, title }) => {
      // Cancel in-flight refetches to prevent overwriting the optimistic update
      await queryClient.cancelQueries({ queryKey: ['conversations', tenantId] });

      // Snapshot current state for rollback
      const previous = queryClient.getQueryData<ConversationSummary[]>(['conversations', tenantId]);

      // Optimistic update: immediately shows new title in sidebar
      queryClient.setQueryData<ConversationSummary[]>(['conversations', tenantId], (old) =>
        old?.map((c) => (c.id === id ? { ...c, title } : c)) ?? []
      );

      return { previous }; // Returned as context for rollback
    },

    onError: (err, _variables, context) => {
      // Roll back to snapshot on failure
      if (context?.previous) {
        queryClient.setQueryData(['conversations', tenantId], context.previous);
      }
    },

    onSettled: () => {
      // Always re-sync from server after mutation completes or errors
      queryClient.invalidateQueries({ queryKey: ['conversations', tenantId] });
    },
  });
}

import { useInfiniteQuery } from '@tanstack/react-query';

export function useMessageHistory(conversationId: string) {
  return useInfiniteQuery({
    queryKey: ['messages', conversationId],
    queryFn: ({ pageParam = null }) =>
      fetch(`/api/conversations/${conversationId}/messages?cursor=${pageParam ?? ''}`)
        .then((r) => r.json() as Promise<{ items: Message[]; nextCursor: string | null }>),
    initialPageParam: null as string | null,
    getNextPageParam: (lastPage) => lastPage.nextCursor,
    // Pages are stored as array of pages; flatten in component
  });
}
